import { useState } from "react";
import { ChevronRight, ArrowLeft, Car, Home, Smartphone, Briefcase, ShoppingCart, Sofa, Shirt, Dog, Bike, ShoppingBag, User } from "lucide-react";
import { Link } from "react-router-dom";

const categories = [
  { name: "Vehicles", icon: <Car className="w-6 h-6 text-red-500" />, subcategories: ["Cars for Sale", "Cars for Rent", "Tyres, Batteries, Oils, & Accessories", "Car Spare Parts", "Motorcycles & Accessories", "Boats - Watercraft", "Heavy Trucks, Buses & Other Vehicles"] },
  { name: "Properties", icon: <Home className="w-6 h-6 text-red-500" />, subcategories: ["Apartments for Sale", "Apartments for Rent", "Villas For Sale", "Villas For Rent", "Vacation Homes for Sale", "Vacation Homes for Rent", "Commercial for Sale", "Commercial for Rent"] },
  { name: "Mobiles & Tablets", icon: <Smartphone className="w-6 h-6 text-red-500" />, subcategories: ["Tablets", "Mobile & Tablet Accessories", "Mobile Numbers"] },
  { name: "Jobs", icon: <Briefcase className="w-6 h-6 text-red-500" />, subcategories: ["Engineering", "Designers", "Customer Service & Call Center", "Workers and Technicians", "Management & Consulting", "Drivers & Delivery", "Education", "HR", "Tourism, Travel & Hospitality", "IT - Telecom", "Marketing and Public Relations", "Medical, Healthcare, & Nursing", "Sales", "Secretarial", "Guards and Security", "Legal - Lawyers", "Other Job"] },
  { name: "Electronics & Appliances", icon: <ShoppingCart className="w-6 h-6 text-red-500" />, subcategories: ["TV - Audio - Video", "Computers - Accessories", "Video games - Consoles", "Cameras - Imaging", "Home Appliances"] },
  { name: "Furniture & Decor", icon: <Sofa className="w-6 h-6 text-red-500" />, subcategories: ["Bathroom", "Bedroom", "Dining Room", "Fabrics - Curtains - Carpets", "Garden - Outdoor", "Home Decoration", "Kitchen - Kitchenware", "Lighting Tools", "Living Room", "Multiple/Other Furniture"] },
  { name: "Fashion & Beauty", icon: <Shirt className="w-6 h-6 text-red-500" />, subcategories: [] },
  { name: "Pets", icon: <Dog className="w-6 h-6 text-red-500" />, subcategories: [] },
  { name: "Kids & Babies", icon: <ShoppingCart className="w-6 h-6 text-red-500" />, subcategories: [] },
  { name: "Hobbies", icon: <Bike className="w-6 h-6 text-red-500" />, subcategories: [] },
  { name: "Businesses & Industrial", icon: <ShoppingBag className="w-6 h-6 text-red-500" />, subcategories: [] },
  { name: "Services", icon: <User className="w-6 h-6 text-red-500" />, subcategories: [] },
];

export default function PostAdPage() {
  const [selectedCategory, setSelectedCategory] = useState(null);

  return (
    <div className="min-h-screen bg-gray-50">
      {/* Header */}
      <header className="bg-white shadow py-4 flex items-center justify-between px-4">
        <Link to="/" className="flex items-center space-x-2 text-gray-700" aria-label="Go back">
          <ArrowLeft className="w-6 h-6" />
          <span className="text-sm">Back</span>
        </Link>
        <Link to="/">
          <img src="/k1.jpeg" alt="Logo" className="w-[100px] h-auto" />
        </Link>
      </header>

      {/* Main Content */}
      <main className="container mx-auto px-4 py-6">
        <h1 className="text-center text-xl font-semibold mb-6">POST YOUR AD</h1>

        {/* Categories or Subcategories */}
        {selectedCategory ? (
          <div className="bg-white shadow-md rounded-md">
            <header className="flex items-center px-4 py-3 border-b space-x-3">
              <button
                onClick={() => setSelectedCategory(null)}
                className="text-gray-500 hover:text-gray-700"
              >
                <ArrowLeft className="w-6 h-6" />
              </button>
              <h2 className="text-gray-600 font-medium">{selectedCategory}</h2>
            </header>
            <ul>
              {categories
                .find((category) => category.name === selectedCategory)
                ?.subcategories.map((subcategory) => (
                  <li key={subcategory} className="px-4 py-3 hover:bg-gray-50 cursor-pointer border-b last:border-none">
                    {subcategory}
                  </li>
                ))}
            </ul>
          </div>
        ) : (
          <div className="bg-white shadow-md rounded-md">
            <h2 className="text-gray-600 font-medium px-4 py-3 border-b">Choose a category</h2>
            <ul>
              {categories.map((category) => (
                <li
                  key={category.name}
                  className="flex items-center justify-between px-4 py-3 cursor-pointer hover:bg-gray-50"
                  onClick={() => setSelectedCategory(category.name)}
                >
                  <span className="flex items-center space-x-3">
                    {category.icon}
                    <span>{category.name}</span>
                  </span>
                  <ChevronRight className="text-gray-400" />
                </li>
              ))}
            </ul>
          </div>
        )}
      </main>
    </div>
  );
}
